mapper.select:
SELECT o.*,v.id AS version_id,v.state AS version_state,t.id AS table_id,t.table_name,
    (SELECT count(*) FROM public.nocode_field f WHERE f.object_version_id=v.id AND f.field_state='ACTIVE' AND f.deleted=0)::integer AS field_count,
    (SELECT count(*) FROM public.nocode_object_table dt WHERE dt.object_version_id=v.id AND dt.table_role='DETAIL' AND coalesce(dt.config_json->>'state','ACTIVE')='ACTIVE' AND dt.deleted=0)::integer AS detail_count,
    (SELECT count(*) FROM public.nocode_relation r WHERE r.object_version_id=v.id AND r.deleted=0)::integer AS relation_count
FROM public.nocode_object o JOIN public.nocode_object_version v ON v.object_id=o.id AND v.version_no=o.latest_version_no
JOIN public.nocode_object_table t ON t.object_version_id=v.id AND t.table_role='MAIN'
WHERE o.deleted=0 AND o.object_name ILIKE #{name} ESCAPE '!' AND o.object_code ILIKE #{code} ESCAPE '!'
AND o.status=#{status}
AND o.source_type=#{source}
AND o.settings_json->>'ownerId'=#{owner}
AND o.category=#{category}
ORDER BY o.update_time DESC,o.id DESC

mapper.update:
 UPDATE public.nocode_field SET config_json=config_json || jsonb_build_object('options',CAST(#{options} AS jsonb)),
     field_state=#{state},data_classification=#{classification},column_name=#{columnName},relation_generated=#{generated}
,update_time=CURRENT_TIMESTAMP,updater=(SELECT updater FROM public.nocode_object_version WHERE id=#{versionId}) WHERE object_version_id=#{versionId} AND stable_field_id=#{fieldId}
